const body = $input.first().json.body || {};

const project = body.project || {};
const cycle = body.cycle || {};
const issues = Array.isArray(body.issues) ? body.issues : [];
const appreciations = Array.isArray(body.appreciations) ? body.appreciations : [];
const observations = Array.isArray(body.observations) ? body.observations : [];
const clientQuestions = Array.isArray(body.clientQuestions) ? body.clientQuestions : [];
const sessions = Array.isArray(body.sessions) ? body.sessions : [];
const messages = Array.isArray(body.messages) ? body.messages : [];
const isQuickCheckin = body.summaryType === 'quick_checkin_poc' || cycle.cycleType === 'quick_checkin';
const isPocSummary = isQuickCheckin || body.summaryType === 'feedback_poc';
const poc = body.poc || {};
const session = sessions[0] || {};

const line = (value) => value == null ? '' : String(value);
const csat = isPocSummary ? body.csatScore : cycle.csatScore;
const score = csat == null ? 'not rated' : `${csat}/10`;
const outcomeLabels = {
  all_good: 'All good',
  feedback_shared: 'Feedback shared',
  needs_improvement: 'Awaiting details'
};
const clientMessages = messages
  .filter((message) => message.side === 'client' && message.metadata?.ignoredForConversation !== true)
  .map((message) => line(message.body).trim())
  .filter(Boolean);
const quickFeedback = line(body.quickCheckinDetail).trim() || clientMessages.join('\n');

const byOwner = new Map();
for (const issue of issues) {
  const key = issue.owner ? issue.owner.name : 'Unassigned';
  if (!byOwner.has(key)) byOwner.set(key, []);
  byOwner.get(key).push(issue);
}

const parts = [];
parts.push(isQuickCheckin
  ? `${project.name || 'Project'} — quick check-in summary`
  : `${project.name || 'Project'} — ${isPocSummary ? 'POC feedback summary' : 'feedback cycle complete'}`);
parts.push('');
parts.push(`Client:      ${project.clientName || '-'}`);
if (isPocSummary) parts.push(`Client POC:  ${poc.name || session.pocName || '-'}`);
parts.push(`Cycle:       ${isQuickCheckin ? 'Quick check-in' : cycle.cycleType === 'project_end' ? 'Project-end feedback' : '30-day feedback'}`);
if (isQuickCheckin) {
  parts.push(`Outcome:     ${outcomeLabels[body.quickCheckinOutcome] || body.quickCheckinOutcome || 'Response received'}`);
  parts.push('');
  parts.push('CLIENT RESPONSE');
  parts.push(`  ${quickFeedback || 'The client selected All good and did not add further text.'}`);
} else {
  parts.push(`Overall CSAT: ${score}`);
  if (cycle.cycleType === 'project_end') parts.push(`NPS:          ${body.npsScore == null ? 'not rated' : `${body.npsScore}/10`}`);
  if (isPocSummary) {
    parts.push(`Status:       ${session.completionStatus || session.status || '-'}`);
    parts.push('');
    parts.push('CLIENT RESPONSE (including additions during the correction window)');
    parts.push(clientMessages.join('\n') || 'No written response recorded.');
  }
}
parts.push('');

if (issues.length) {
  parts.push(`WHAT NEEDS ATTENTION (${issues.length})`);
  parts.push('');
  for (const [owner, list] of byOwner) {
    parts.push(`  ${owner}${list[0].manager ? ` (manager: ${list[0].manager.name})` : ''}`);
    for (const issue of list) {
      parts.push(`   - [${line(issue.severity).toUpperCase()}] ${issue.serviceName || 'Project'}: ${issue.title}`);
      if (issue.rootCause) parts.push(`     ${issue.rootCause}`);
      if (issue.raisedBy) parts.push(`     raised by ${issue.raisedBy}`);
    }
    parts.push('');
  }
} else {
  parts.push('WHAT NEEDS ATTENTION');
  parts.push('  Nothing requiring action was recorded.');
  parts.push('');
}

if (appreciations.length) {
  parts.push(`WHAT THE CLIENT PRAISED (${appreciations.length})`);
  for (const item of appreciations) {
    parts.push(`   - ${item.subject || 'Appreciation'}${item.owner ? ` (${item.owner.name})` : ''}: ${item.detail}`);
  }
  parts.push('');
}

if (observations.length) {
  parts.push(`OTHER POINTS RAISED (${observations.length})`);
  for (const item of observations) {
    parts.push(`   - ${item.topic}: ${item.detail}`);
  }
  parts.push('');
}

if (clientQuestions.length) {
  parts.push(`CLIENT QUESTIONS / FOLLOW-UP NEEDED (${clientQuestions.length})`);
  for (const item of clientQuestions) {
    parts.push(`   - ${line(item.text || item)}`);
  }
  parts.push('');
}

parts.push(`Open the conversation: ${line(body.resumeUrl)}`);
parts.push('');
parts.push(isQuickCheckin
  ? 'This summary was sent for this POC after the 10-minute quick check-in response window closed.'
  : isPocSummary ? 'This summary covers this POC only, after their response window or session closed. Other POCs may still be responding.' : 'This is the single summary for the completed feedback cycle.');

const handoffEmail = $('Config').first().json.CSAT_HANDOFF_EMAIL;
const recipients = [...new Set((
  isQuickCheckin ? [handoffEmail] : [...(body.recipients || []), handoffEmail]
).filter(Boolean))];

return [{
  json: {
    to: recipients.join(','),
    subject: isQuickCheckin
      ? `CSAT Quick Check-in: ${project.name || 'Project'} — ${poc.name || session.pocName || 'Client POC'} — ${issues.length} to action`
      : `CSAT: ${project.name || 'Project'}${isPocSummary ? ` — ${poc.name || session.pocName || 'Client POC'}` : ''} — ${issues.length} to action, ${appreciations.length} appreciation${appreciations.length === 1 ? '' : 's'}, ${clientQuestions.length} question${clientQuestions.length === 1 ? '' : 's'}`,
    text: parts.join('\n'),
    summaryType: isQuickCheckin ? 'quick_checkin_poc' : isPocSummary ? 'feedback_poc' : 'feedback_cycle',
    issueCount: issues.length,
    appreciationCount: appreciations.length,
    questionCount: clientQuestions.length,
    recipientCount: recipients.length
  }
}];
